// Copies the export golden media (generated by packages/export/golden/make-media.mjs) into public/
// so the preview can play it at /golden/media/*. The copy is gitignored.
import { cpSync, existsSync, mkdirSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const app = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const source = path.resolve(app, "../../packages/export/golden/media");
if (!existsSync(path.join(source, "golden-font.ttf"))) {
    console.error(`missing ${source}: run pnpm --filter @opennan/export exec node golden/make-media.mjs`);
    process.exit(1);
}
const target = path.join(app, "public/golden/media");
mkdirSync(target, { recursive: true });
cpSync(source, target, { recursive: true });
console.log(`copied golden media to ${path.relative(app, target)}`);
